import re

def get_factors(text):
    match = re.search(r'(\d+(?:,\s*\d+)*)', text)
    if match:
        return match.group(0).replace(' ', '')
    else:
        return 'NONE'

# Test the function
text = '7411 is not a prime number. It can be factorized as 3 × 3 × 7 × 13.'
print(get_factors(text))  # Output: 3,3,7,13
